"""Genesis 1-11 script for engine5. Each scene: env + beats. Beats carry narration (nar, used in 'nar' mode),
character lines (used in both modes unless tagged), min duration, sfx. Actions reference (beat, offset) or ("L", beat, line, offset)."""
HZ = 186
GY = HZ + 56   # default feet line for cast

def C(n, x, y=GY, **kw): d = dict(n=n, x=x, y=y, s=0.72); d.update(kw); return d
def B(nar=None, lines=(), dur=0.0, sfx=(), **kw): d = dict(nar=nar, lines=list(lines), dur=dur, sfx=list(sfx)); d.update(kw); return d
def L(b, i=0, off=0.0): return ("L", b, i, off)

